  1→import { spawn } from 'node:child_process'
  2→import * as fs from 'node:fs'
  3→import * as path from 'node:path'
  4→import * as os from 'node:os'
  5→import { expandHome } from './config.js'
  6→
  7→const DEFAULT_PID_PATH = path.join(os.homedir(), '.openacp', 'openacp.pid')
  8→const DEFAULT_LOG_DIR = path.join(os.homedir(), '.openacp', 'logs')
  9→
 10→export function writePidFile(pidPath: string, pid: number): void {
 11→  const dir = path.dirname(pidPath)
 12→  fs.mkdirSync(dir, { recursive: true })
 13→  fs.writeFileSync(pidPath, String(pid))
 14→}
 15→
 16→export function readPidFile(pidPath: string): number | null {
 17→  try {
 18→    const content = fs.readFileSync(pidPath, 'utf-8').trim()
 19→    const pid = parseInt(content, 10)
 20→    return isNaN(pid) ? null : pid
 21→  } catch {
 22→    return null
 23→  }
 24→}
 25→
 26→export function removePidFile(pidPath: string): void {
 27→  try {
 28→    fs.unlinkSync(pidPath)
 29→  } catch {
 30→    // ignore if already gone
 31→  }
 32→}
 33→
 34→export function isProcessRunning(pidPath: string): boolean {
 35→  const pid = readPidFile(pidPath)
 36→  if (pid === null) return false
 37→  try {
 38→    process.kill(pid, 0)
 39→    return true
 40→  } catch {
 41→    // Process not running, clean up stale PID file
 42→    removePidFile(pidPath)
 43→    return false
 44→  }
 45→}
 46→
 47→export function getStatus(pidPath: string = DEFAULT_PID_PATH): { running: boolean; pid?: number } {
 48→  const pid = readPidFile(pidPath)
 49→  if (pid === null) return { running: false }
 50→  try {
 51→    process.kill(pid, 0)
 52→    return { running: true, pid }
 53→  } catch {
 54→    removePidFile(pidPath)
 55→    return { running: false }
 56→  }
 57→}
 58→
 59→export function startDaemon(pidPath: string = DEFAULT_PID_PATH, logDir?: string): { pid: number } | { error: string } {
 60→  // Check if already running
 61→  if (isProcessRunning(pidPath)) {
 62→    const pid = readPidFile(pidPath)!
 63→    return { error: `Already running (PID ${pid})` }
 64→  }
 65→
 66→  const resolvedLogDir = logDir ? expandHome(logDir) : DEFAULT_LOG_DIR
 67→  fs.mkdirSync(resolvedLogDir, { recursive: true })
 68→  const logFile = path.join(resolvedLogDir, 'openacp.log')
 69→
 70→  // Find the CLI entry point
 71→  const cliPath = path.resolve(process.argv[1])
 72→  const nodePath = process.execPath
 73→
 74→  const out = fs.openSync(logFile, 'a')
 75→  const err = fs.openSync(logFile, 'a')
 76→
 77→  const child = spawn(nodePath, [cliPath, '--daemon-child'], {
 78→    detached: true,
 79→    stdio: ['ignore', out, err],
 80→  })
 81→
 82→  // Close file descriptors in parent — child has its own copies
 83→  fs.closeSync(out)
 84→  fs.closeSync(err)
 85→
 86→  if (!child.pid) {
 87→    return { error: 'Failed to spawn daemon process' }
 88→  }
 89→
 90→  writePidFile(pidPath, child.pid)
 91→  child.unref()
 92→
 93→  return { pid: child.pid }
 94→}
 95→
 96→export function stopDaemon(pidPath: string = DEFAULT_PID_PATH): { stopped: boolean; pid?: number; error?: string } {
 97→  const pid = readPidFile(pidPath)
 98→  if (pid === null) return { stopped: false, error: 'Not running (no PID file)' }
 99→
100→  try {
101→    process.kill(pid, 0) // check alive
102→  } catch {
103→    removePidFile(pidPath)
104→    return { stopped: false, error: 'Not running (stale PID file removed)' }
105→  }
106→
107→  try {
108→    process.kill(pid, 'SIGTERM')
109→    // PID file is cleaned up by the child process on SIGTERM (see main.ts shutdown handler).
110→    // Also remove here in case child crashes before cleanup.
111→    removePidFile(pidPath)
112→    return { stopped: true, pid }
113→  } catch (e) {
114→    return { stopped: false, error: `Failed to stop: ${(e as Error).message}` }
115→  }
116→}
117→
118→export function getPidPath(): string {
119→  return DEFAULT_PID_PATH
120→}
