  1→import { execFileSync } from 'node:child_process'
  2→import * as fs from 'node:fs'
  3→import * as path from 'node:path'
  4→import * as os from 'node:os'
  5→import { createChildLogger } from './log.js'
  6→
  7→const log = createChildLogger({ module: 'autostart' })
  8→
  9→const LAUNCHD_LABEL = 'com.openacp.daemon'
 10→const LAUNCHD_PLIST_PATH = path.join(os.homedir(), 'Library', 'LaunchAgents', `${LAUNCHD_LABEL}.plist`)
 11→const SYSTEMD_SERVICE_PATH = path.join(os.homedir(), '.config', 'systemd', 'user', 'openacp.service')
 12→
 13→export function isAutoStartSupported(): boolean {
 14→  return process.platform === 'darwin' || process.platform === 'linux'
 15→}
 16→
 17→export function generateLaunchdPlist(nodePath: string, cliPath: string, logDir: string): string {
 18→  const logFile = path.join(logDir, 'openacp.log')
 19→  return `<?xml version="1.0" encoding="UTF-8"?>
 20→<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
 21→<plist version="1.0">
 22→<dict>
 23→  <key>Label</key>
 24→  <string>${LAUNCHD_LABEL}</string>
 25→  <key>ProgramArguments</key>
 26→  <array>
 27→    <string>${nodePath}</string>
 28→    <string>${cliPath}</string>
 29→    <string>--daemon-child</string>
 30→  </array>
 31→  <key>RunAtLoad</key>
 32→  <true/>
 33→  <key>KeepAlive</key>
 34→  <true/>
 35→  <key>StandardOutPath</key>
 36→  <string>${logFile}</string>
 37→  <key>StandardErrorPath</key>
 38→  <string>${logFile}</string>
 39→</dict>
 40→</plist>
 41→`
 42→}
 43→
 44→export function generateSystemdUnit(nodePath: string, cliPath: string): string {
 45→  return `[Unit]
 46→Description=OpenACP Daemon
 47→
 48→[Service]
 49→ExecStart=${nodePath} ${cliPath} --daemon-child
 50→Restart=on-failure
 51→
 52→[Install]
 53→WantedBy=default.target
 54→`
 55→}
 56→
 57→export function installAutoStart(logDir: string): { success: boolean; error?: string } {
 58→  if (!isAutoStartSupported()) {
 59→    return { success: false, error: 'Auto-start not supported on this platform' }
 60→  }
 61→
 62→  const nodePath = process.execPath
 63→  const cliPath = path.resolve(process.argv[1])
 64→  const resolvedLogDir = logDir.startsWith('~')
 65→    ? path.join(os.homedir(), logDir.slice(1))
 66→    : logDir
 67→
 68→  try {
 69→    if (process.platform === 'darwin') {
 70→      const plist = generateLaunchdPlist(nodePath, cliPath, resolvedLogDir)
 71→      const dir = path.dirname(LAUNCHD_PLIST_PATH)
 72→      fs.mkdirSync(dir, { recursive: true })
 73→      fs.writeFileSync(LAUNCHD_PLIST_PATH, plist)
 74→      execFileSync('launchctl', ['load', LAUNCHD_PLIST_PATH], { stdio: 'pipe' })
 75→      log.info('LaunchAgent installed')
 76→      return { success: true }
 77→    }
 78→
 79→    if (process.platform === 'linux') {
 80→      const unit = generateSystemdUnit(nodePath, cliPath)
 81→      const dir = path.dirname(SYSTEMD_SERVICE_PATH)
 82→      fs.mkdirSync(dir, { recursive: true })
 83→      fs.writeFileSync(SYSTEMD_SERVICE_PATH, unit)
 84→      execFileSync('systemctl', ['--user', 'daemon-reload'], { stdio: 'pipe' })
 85→      execFileSync('systemctl', ['--user', 'enable', 'openacp'], { stdio: 'pipe' })
 86→      log.info('systemd user service installed')
 87→      return { success: true }
 88→    }
 89→
 90→    return { success: false, error: 'Unsupported platform' }
 91→  } catch (e) {
 92→    const msg = (e as Error).message
 93→    log.error({ err: msg }, 'Failed to install auto-start')
 94→    return { success: false, error: msg }
 95→  }
 96→}
 97→
 98→export function uninstallAutoStart(): { success: boolean; error?: string } {
 99→  if (!isAutoStartSupported()) {
100→    return { success: false, error: 'Auto-start not supported on this platform' }
101→  }
102→
103→  try {
104→    if (process.platform === 'darwin') {
105→      if (fs.existsSync(LAUNCHD_PLIST_PATH)) {
106→        try {
107→          execFileSync('launchctl', ['unload', LAUNCHD_PLIST_PATH], { stdio: 'pipe' })
108→        } catch {
109→          // may already be unloaded
110→        }
111→        fs.unlinkSync(LAUNCHD_PLIST_PATH)
112→        log.info('LaunchAgent removed')
113→      }
114→      return { success: true }
115→    }
116→
117→    if (process.platform === 'linux') {
118→      if (fs.existsSync(SYSTEMD_SERVICE_PATH)) {
119→        try {
120→          execFileSync('systemctl', ['--user', 'disable', 'openacp'], { stdio: 'pipe' })
121→        } catch {
122→          // may already be disabled
123→        }
124→        fs.unlinkSync(SYSTEMD_SERVICE_PATH)
125→        execFileSync('systemctl', ['--user', 'daemon-reload'], { stdio: 'pipe' })
126→        log.info('systemd user service removed')
127→      }
128→      return { success: true }
129→    }
130→
131→    return { success: false, error: 'Unsupported platform' }
132→  } catch (e) {
133→    const msg = (e as Error).message
134→    log.error({ err: msg }, 'Failed to uninstall auto-start')
135→    return { success: false, error: msg }
136→  }
137→}
138→
139→export function isAutoStartInstalled(): boolean {
140→  if (process.platform === 'darwin') {
141→    return fs.existsSync(LAUNCHD_PLIST_PATH)
142→  }
143→  if (process.platform === 'linux') {
144→    return fs.existsSync(SYSTEMD_SERVICE_PATH)
145→  }
146→  return false
147→}
