437→  async sendSkillCommands(sessionId: string, commands: AgentCommand[]): Promise<void> {
438→    const session = (this.core as OpenACPCore).sessionManager.getSession(sessionId);
439→    if (!session) return;
440→    const threadId = Number(session.threadId);
441→    if (!threadId) return;
442→
443→    // Empty commands → remove pinned message
444→    if (commands.length === 0) {
445→      await this.cleanupSkillCommands(sessionId);
446→      return;
447→    }
448→
449→    // Clear old callback entries before building new keyboard
450→    clearSkillCallbacks(sessionId);
451→
452→    const keyboard = buildSkillKeyboard(sessionId, commands);
453→    const text = "🛠 <b>Available commands:</b>";
454→    const existingMsgId = this.skillMessages.get(sessionId);
455→
456→    if (existingMsgId) {
457→      // Update existing pinned message
458→      try {
459→        await this.bot.api.editMessageText(
460→          this.telegramConfig.chatId,
461→          existingMsgId,
462→          text,
463→          { parse_mode: "HTML", reply_markup: keyboard },
464→        );
465→        return;
466→      } catch {
467→        // Message may have been deleted — fall through to create new
468→      }
469→    }
470→
471→    // Create and pin new message
472→    try {
473→      const msg = await this.bot.api.sendMessage(
474→        this.telegramConfig.chatId,
475→        text,
476→        {
477→          message_thread_id: threadId,
478→          parse_mode: "HTML",
479→          reply_markup: keyboard,
480→          disable_notification: true,
481→        },
482→      );
483→      this.skillMessages.set(sessionId, msg.message_id);
484→
485→      await this.bot.api.pinChatMessage(this.telegramConfig.chatId, msg.message_id, {
486→        disable_notification: true,
487→      });
488→    } catch (err) {
489→      log.error({ err, sessionId }, "Failed to send skill commands");
490→    }
491→
492→    // Update Telegram autocomplete with skill commands
493→    await this.updateCommandAutocomplete(session.agentName, commands);
494→  }
