496→  async cleanupSkillCommands(sessionId: string): Promise<void> {
497→    const msgId = this.skillMessages.get(sessionId);
498→    if (!msgId) return;
499→
500→    try {
501→      await this.bot.api.editMessageText(
502→        this.telegramConfig.chatId,
503→        msgId,
504→        "🛠 <i>Session ended</i>",
505→        { parse_mode: "HTML" },
506→      );
507→      await this.bot.api.unpinChatMessage(this.telegramConfig.chatId, msgId);
508→    } catch {
509→      /* message may already be deleted */
510→    }
511→
512→    this.skillMessages.delete(sessionId);
513→    clearSkillCallbacks(sessionId);
514→
515→  }
