517→  private async updateCommandAutocomplete(agentName: string, skillCommands: AgentCommand[]): Promise<void> {
518→    // Telegram requires: 1-32 chars, lowercase a-z, 0-9, underscores only
519→    const prefix = `[${agentName}] `;
520→    const validSkills = skillCommands
521→      .map((c) => ({
522→        command: c.name.toLowerCase().replace(/[^a-z0-9_]/g, "_").slice(0, 32),
523→        description: (prefix + ((c.description || c.name).replace(/\n/g, " "))).slice(0, 256),
524→      }))
525→      .filter((c) => c.command.length > 0);
526→    const all = [...STATIC_COMMANDS, ...validSkills];
527→    try {
528→      await this.bot.api.setMyCommands(all, {
529→        scope: { type: "chat", chat_id: this.telegramConfig.chatId },
530→      });
531→      log.info({ count: all.length, skills: validSkills.length }, "Updated command autocomplete");
532→    } catch (err) {
533→      log.error({ err, commands: all }, "Failed to update command autocomplete");
534→    }
535→  }
