106→async function detectChatId(token: string): Promise<number> {
107→  // Clear old updates
108→  let lastUpdateId = 0;
109→  try {
110→    const clearRes = await fetch(
111→      `https://api.telegram.org/bot${token}/getUpdates?offset=-1`,
112→    );
113→    const clearData = (await clearRes.json()) as {
114→      ok: boolean;
115→      result?: Array<{ update_id: number }>;
116→    };
117→    if (clearData.ok && clearData.result?.length) {
118→      lastUpdateId = clearData.result[clearData.result.length - 1].update_id;
119→    }
120→  } catch {
121→    // ignore
122→  }
123→
124→  console.log("");
125→  console.log(`  ${c.bold}If you don't have a supergroup yet:${c.reset}`);
126→  console.log(dim("  1. Open Telegram → New Group → add your bot"));
127→  console.log(dim("  2. Group Settings → convert to Supergroup"));
128→  console.log(dim("  3. Enable Topics in group settings"));
129→  console.log("");
130→  console.log(`  ${c.bold}Then send "hi" in the group.${c.reset}`);
131→  console.log(
132→    dim(
133→      `  Listening... press ${c.reset}${c.yellow}m${c.reset}${c.dim} to enter ID manually`,
134→    ),
135→  );
136→  console.log("");
137→
138→  const MAX_ATTEMPTS = 120;
139→  const POLL_INTERVAL = 1000;
140→
141→  // Listen for 'm' keypress to switch to manual
142→  let cancelled = false;
143→  const onKeypress = (data: Buffer) => {
144→    const key = data.toString();
145→    if (key === "m" || key === "M") {
146→      cancelled = true;
147→    }
148→  };
149→  if (process.stdin.isTTY) {
150→    process.stdin.setRawMode(true);
151→    process.stdin.resume();
152→    process.stdin.on("data", onKeypress);
153→  }
154→
155→  const cleanup = () => {
156→    if (process.stdin.isTTY) {
157→      process.stdin.removeListener("data", onKeypress);
158→      process.stdin.setRawMode(false);
159→      process.stdin.pause();
160→    }
161→  };
162→
163→  try {
164→    for (let i = 0; i < MAX_ATTEMPTS; i++) {
165→      if (cancelled) {
166→        cleanup();
167→        return promptManualChatId();
168→      }
169→
170→      try {
171→        const offset = lastUpdateId ? lastUpdateId + 1 : 0;
172→        const res = await fetch(
173→          `https://api.telegram.org/bot${token}/getUpdates?offset=${offset}&timeout=1`,
174→        );
175→        const data = (await res.json()) as {
176→          ok: boolean;
177→          result?: Array<{
178→            update_id: number;
179→            message?: {
180→              chat: { id: number; title?: string; type: string };
181→            };
182→            my_chat_member?: {
183→              chat: { id: number; title?: string; type: string };
184→            };
185→          }>;
186→        };
187→
188→        if (!data.ok || !data.result?.length) {
189→          await new Promise((r) => setTimeout(r, POLL_INTERVAL));
190→          continue;
191→        }
192→
193→        const groups = new Map<number, string>();
194→        for (const update of data.result) {
195→          lastUpdateId = update.update_id;
196→          const chat = update.message?.chat ?? update.my_chat_member?.chat;
197→          if (chat && (chat.type === "supergroup" || chat.type === "group")) {
198→            groups.set(chat.id, chat.title ?? String(chat.id));
199→          }
200→        }
201→
202→        if (groups.size === 1) {
203→          const [id, title] = [...groups.entries()][0];
204→          console.log(
205→            ok(`Group detected: ${c.bold}${title}${c.reset}${c.green} (${id})`),
206→          );
207→          cleanup();
208→          return id;
209→        }
210→
211→        if (groups.size > 1) {
212→          cleanup();
213→          const choices = [...groups.entries()].map(([id, title]) => ({
214→            name: `${title} (${id})`,
215→            value: id,
216→          }));
217→          return select({
218→            message: "Multiple groups found. Pick one:",
219→            choices,
220→          });
221→        }
222→      } catch {
223→        // Network error, retry
224→      }
225→      await new Promise((r) => setTimeout(r, POLL_INTERVAL));
226→    }
227→
228→    console.log(warn("Timed out waiting for messages."));
229→    cleanup();
230→    return promptManualChatId();
231→  } catch (err) {
232→    cleanup();
233→    throw err;
234→  }
235→}
