241→];
242→
243→function commandExists(cmd: string): boolean {
244→  try {
245→    execFileSync("which", [cmd], { stdio: "pipe" });
246→    return true;
247→  } catch {
248→    // not in PATH
249→  }
250→  let dir = process.cwd();
251→  while (true) {
252→    const binPath = path.join(dir, "node_modules", ".bin", cmd);
253→    if (fs.existsSync(binPath)) return true;
254→    const parent = path.dirname(dir);
255→    if (parent === dir) break;
256→    dir = parent;
257→  }
258→  return false;
259→}
