261→export async function detectAgents(): Promise<
262→  Array<{ name: string; command: string }>
263→> {
264→  const found: Array<{ name: string; command: string }> = [];
265→  for (const agent of KNOWN_AGENTS) {
266→    const available: string[] = [];
267→    for (const cmd of agent.commands) {
268→      if (commandExists(cmd)) {
269→        available.push(cmd);
270→      }
271→    }
272→    if (available.length > 0) {
273→      found.push({ name: agent.name, command: available[0] });
274→    }
275→  }
276→  return found;
277→}
