  for (const adapter of this.adapters.values()) {
    await adapter.start()  // Calls TelegramAdapter.start(), etc.
  }
}
```

---

### 5. ONBOARDING & RUN MODE SELECTION

#### **Setup Flow** (`src/core/setup.ts`, lines 417-472):

The onboarding has 3 main steps:

1. **[1/3] Telegram Bot** — Bot token & chat ID validation
2. **[2/3] Workspace** — Base directory for workspaces
3. **[3/3] Run Mode** — Choose daemon or foreground

#### **Run Mode Step** (lines 365-405):

```typescript
export async function setupRunMode(): Promise<{ 
  runMode: 'foreground' | 'daemon'
  autoStart: boolean 
}> {
  // Windows doesn't support daemon mode
  if (process.platform === 'win32') {
    return { runMode: 'foreground', autoStart: false }
  }

  const mode = await select({
    message: 'How would you like to run OpenACP?',
    choices: [
      {
        name: 'Background (daemon)',
        value: 'daemon',
        description: 'Runs silently, auto-starts on boot. Manage with: openacp status | stop | logs'
      },
      {
        name: 'Foreground (terminal)',
        value: 'foreground',
        description: 'Runs in current terminal session. Start with: openacp'
      }
    ]
  })

  if (mode === 'daemon') {
    const { installAutoStart, isAutoStartSupported } = await import('./autostart.js')
    const autoStart = isAutoStartSupported()
    if (autoStart) {
      const result = installAutoStart(expandHome('~/.openacp/logs'))
      if (result.success) {
        console.log(ok('Auto-start on boot enabled'))
      }
    }
    return { runMode: 'daemon', autoStart }
  }

  return { runMode: 'foreground', autoStart: false }
}
```

