// 0. If running as daemon child, write PID file and check for existing instance
if (process.argv.includes('--daemon-child')) {
  const { writePidFile, readPidFile, getPidPath } = await import('./core/daemon.js')
  const pidPath = getPidPath()
  const existingPid = readPidFile(pidPath)
  if (existingPid !== null && existingPid !== process.pid) {
    // Check if the existing PID is actually alive
    try {
      process.kill(existingPid, 0)
      // Process is alive and it's not us — bail out
      console.error(`Another OpenACP instance is already running (PID ${existingPid}). Exiting.`)
      process.exit(1)
    } catch {
      // Stale PID file — safe to overwrite
    }
  }
  writePidFile(pidPath, process.pid)
}

